// Root screen: catalog filters and results on the left, the selected event's
// record (or the association form) on the right. No separate results-table
// component: the list is specific enough to this screen that inlining it
// here beats a component with one caller. All request orchestration and all
// user-facing error text live in this file.
import { useState } from "<MSG:0>";
import {
  ApiError,
  associateDetections,
  getEvent,
  searchEvents,
  type AssociateRequest,
  type CatalogBounds,
  type EventDetail as EventDetailData,
  type EventSummary,
} from "<PATH:0>";
import { AssociationForm } from "<PATH:1>";
import { EventDetail } from "<PATH:2>";

const EMPTY_BOUNDS: CatalogBounds = {
  from: "<EMPTY:0>", to: "<EMPTY:0>", minMagnitude: -2, maxMagnitude: 9,
  minLat: -90, maxLat: 90, minLon: -180, maxLon: 180, limit: 50,
};

export function App() {
  const [bounds, setBounds] = useState<CatalogBounds>(EMPTY_BOUNDS);
  const [events, setEvents] = useState<EventSummary[]>([]);
  const [count, setCount] = useState<number | null>(null);
  const [selected, setSelected] = useState<EventDetailData | null>(null);
  const [associating, setAssociating] = useState(false);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const describe = (err: unknown): string => {
    if (err instanceof ApiError) {
      return `<MSG:1>`;
    }
    return "<MSG:2>";
  };

  const runSearch = async () => {
    setLoading(true);
    setError(null);
    setSelected(null);
    setAssociating(false);
    try {
      const res = await searchEvents(bounds);
      setEvents(res.events);
      setCount(res.count);
    } catch (err) {
      setEvents([]);
      setCount(null);
      setError(describe(err));
    } finally {
      setLoading(false);
    }
  };

  const openEvent = async (eventId: string) => {
    setLoading(true);
    setError(null);
    setAssociating(false);
    try {
      setSelected(await getEvent(eventId));
    } catch (err) {
      setSelected(null);
      setError(describe(err));
    } finally {
      setLoading(false);
    }
  };

  const runAssociate = async (req: AssociateRequest) => {
    setSaving(true);
    setError(null);
    try {
      setSelected(await associateDetections(req));
      setAssociating(false);
    } catch (err) {
      setError(describe(err));
    } finally {
      setSaving(false);
    }
  };

  const setField = (key: keyof CatalogBounds, value: number | string) => {
    setBounds({ ...bounds, [key]: value });
  };

  return (
    <div className="<MSG:3>">
      <header className="<MSG:4>">
        <div>
          <h1>tremorline</h1>
          <p>Ridgeline Regional Array — seismic event catalog</p>
        </div>
        <button type="<MSG:5>" className="<MSG:6>" onClick={() => setAssociating(true)}>
          Associate detections
        </button>
      </header>

      {error !== null && <p className="<MSG:7>">{error}</p>}

      <main className="<MSG:8>">
        <section className="<MSG:9>">
          <form className="<MSG:10>" onSubmit={(e) => { e.preventDefault(); runSearch(); }}>
            <label htmlFor="<SQL:0>">From</label>
            <input id="<SQL:0>" type="<MSG:11>" value={bounds.from}
              onChange={(e) => setField("<SQL:1>", e.target.value)} />
            <label htmlFor="<MSG:12>">To</label>
            <input id="<MSG:12>" type="<MSG:11>" value={bounds.to}
              onChange={(e) => setField("<MSG:13>", e.target.value)} />
            <label htmlFor="<MSG:14>">Min magnitude</label>
            <input id="<MSG:14>" value={bounds.minMagnitude}
              onChange={(e) => setField("<MSG:15>", Number(e.target.value))} />
            <label htmlFor="<MSG:16>">Max magnitude</label>
            <input id="<MSG:16>" value={bounds.maxMagnitude}
              onChange={(e) => setField("<MSG:17>", Number(e.target.value))} />
            <button type="<MSG:18>" className="<MSG:19>" disabled={loading}>
              Search
            </button>
          </form>
          {loading && <p className="<MSG:20>">Working…</p>}
          {count !== null && <p className="<MSG:21>">{count} events matched</p>}
          {events.length === 0 ? (
            <p className="<MSG:22>">No events matched those bounds.</p>
          ) : (
            <table className="<MSG:23>">
              <thead>
                <tr>
                  <th>Event id</th>
                  <th>Origin time</th>
                  <th>Magnitude</th>
                  <th>Depth (km)</th>
                </tr>
              </thead>
              <tbody>
                {events.map((ev) => (
                  <tr
                    key={ev.eventId}
                    className={ev.eventId === selected?.eventId ? "<MSG:24>" : "<EMPTY:0>"}
                    onClick={() => openEvent(ev.eventId)}
                  >
                    <td>{ev.eventId}</td>
                    <td>{ev.originTime}</td>
                    <td>{ev.magnitude !== undefined ? ev.magnitude.toFixed(2) : "<MSG:25>"}</td>
                    <td>{ev.depthKm.toFixed(1)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </section>

        <section className="<MSG:26>">
          {associating && (
            <AssociationForm
              saving={saving}
              onCancel={() => setAssociating(false)}
              onAssociate={runAssociate}
            />
          )}
          {!associating && selected === null && (
            <p className="<MSG:22>">Select an event to see its record.</p>
          )}
          {!associating && selected !== null && (
            <EventDetail event={selected} onAssociate={() => setAssociating(true)} />
          )}
        </section>
      </main>
    </div>
  );
}

